style.css:
@-moz-document url-prefix("https://www.bandlab.com/studio") {
/* General body and background */
  body, .sc-eCImPb, .sc-hmdomO {
    background-color: #000 !important;
    color: #C0C0C0 !important;
  }

  /* Make all text silver */
  * {
    color: #C0C0C0 !important;
    background-color: transparent !important;
    box-shadow: none !important;
  }

  /* Outlines for buttons */
  button, .sc-eDvSVe, .sc-dxgOiQ, .sc-jSMfEi, .sc-kLgntA {
    border: 1px solid white !important;
    background-color: transparent !important;
    color: #C0C0C0 !important;
  }

  /* Inputs and dropdowns */
  input, select, textarea {
    background-color: black !important;
    color: #C0C0C0 !important;
    border: 1px solid white !important;
  }

  /* Remove background images or shadows */
  [style*="background-image"], [class*="background"] {
    background: none !important;
  }

  /* Sliders, knobs, etc. */
  .sc-hGoxap, .sc-hlTVkV {
    filter: grayscale(100%) brightness(150%);
    border: 1px solid white !important;
  }

  /* Hover effects */
  button:hover, .sc-dxgOiQ:hover {
    background-color: #111 !important;
    color: white !important;
    border-color: #C0C0C0 !important;
  }

  /* Scrollbars (optional) */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: black;
  }
  ::-webkit-scrollbar-thumb {
    background: white;
    border-radius: 4px;
  }

  /* Optional: hide logos or other decorative elements */
  img, svg, .logo, .sc-jIAOiI {
    filter: grayscale(100%) brightness(200%) !important;
  }
}
